28	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
29	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
30	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
31	    @Mapping(target = "locality", expression = "java(locality(owner))")
32	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "bulkSignupWarning", ignore = true)
36	    @Mapping(target = "identityKey", ignore = true)
