38	    @Mapping(target = "possibleDuplicateOf", ignore = true)
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    /**
42	     * Derives the owner's {@code salutation} from its optional {@code title} and its {@code lastName}:
43	     * the title, a single space and the last name when a title is present (e.g. {@code 'DR Franklin'}),
44	     * otherwise just the last name. A {@code null} or blank title yields the bare last name.
45	     *
46	     * @param owner the owner being mapped
47	     * @return the derived salutation
48	     */
49	    default String salutation(Owner owner) {
50	        String title = owner.getTitle();
51	        if (title == null || title.isBlank()) {
52	            return owner.getLastName();
53	        }
54	        return title + " " + owner.getLastName();
55	    }
56	
57	    /**
58	     * Derives the owner's {@code contactPreference} from the owner's own fields:
59	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
60	     *
61	     * @param owner the owner being mapped
62	     * @return the derived contact preference
63	     */
64	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
65	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
66	    }
67	
68	    /**
69	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
70	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
71	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
72	     * rather than repeated at each use.
73	     *
74	     * @param owner the owner being mapped
75	     * @return {@code true} when the owner has a non-blank email
76	     */
77	    default boolean hasEmail(Owner owner) {
78	        return owner.getEmail() != null && !owner.getEmail().isBlank();
79	    }
80	
81	    /**
82	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
83	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
84	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
85	     * case the field is absent from the response. The age in whole years is the number of complete
86	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
87	     * registration date is somehow absent the current date is used as the reference.
88	     *
89	     * @param owner the owner being mapped
90	     * @return the derived age band, or {@code null} when no birth date is present
91	     */
92	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
93	        java.time.LocalDate birthDate = owner.getBirthDate();
94	        if (birthDate == null) {
95	            return null;
96	        }
97	        java.time.LocalDate reference = owner.getRegistrationDate() != null
98	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
99	        int age = java.time.Period.between(birthDate, reference).getYears();
100	        if (age < 18) {
101	            return OwnerDto.AgeBandEnum.MINOR;
102	        }
103	        if (age < 65) {
104	            return OwnerDto.AgeBandEnum.ADULT;
105	        }
106	        return OwnerDto.AgeBandEnum.SENIOR;
107	    }
108	
109	    /**
110	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
111	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
112	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
113	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
114	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
115	     * identity keeps the locality consistent with the code an owner is issued.
116	     *
117	     * @param owner the owner being mapped
118	     * @return the derived locality
119	     */
120	    default String locality(Owner owner) {
121	        String code = owner.getCustomerCode();
122	        if (code == null) {
123	            return Region.code(owner.getPostcode(), owner.getCity());
124	        }
125	        int dash = code.indexOf('-');
126	        return dash >= 0 ? code.substring(0, dash) : code;
127	    }
128	
129	    /**
130	     * Derives the owner's {@code timezone} as the IANA name for its {@link #locality(Owner) locality}
131	     * region, resolved through the shared fixed region-to-timezone table
132	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
133	     * {@code QLD -> Australia/Brisbane}) in {@link Region#timezoneForCode(String)}. Deriving it from
134	     * the same locality keeps the timezone consistent with the region the owner is labelled with.
135	     * Returns {@code null} when the locality has no known timezone (such as an {@code UNKNOWN}
136	     * region), in which case the field is absent from the response.
137	     *
138	     * @param owner the owner being mapped
139	     * @return the derived IANA timezone name, or {@code null} when the region has no known timezone
140	     */
141	    default String timezone(Owner owner) {
142	        return Region.timezoneForCode(locality(owner));
143	    }
144	
145	    /**
146	     * Derives the owner's {@code membershipPoints} from the owner's factors. Starts at {@code 0},
147	     * adds {@code 2} when an email is present, adds {@code 1} when the owner's {@code namesakeCount}
148	     * is {@code 0}, adds {@code 2} for a household of {@code 3} or more (see
149	     * {@link Owner#getHouseholdSize()}), and adds {@code 3} when the owner's tenure &mdash; the number
150	     * of elapsed fiscal years between its {@code registrationDate} and the current date &mdash; exceeds
151	     * one fiscal year (see {@link #tenureFiscalYears(Owner)}).
152	     *
153	     * @param owner the owner being mapped
154	     * @return the derived membership points
155	     */
156	    default Integer membershipPoints(Owner owner) {
157	        int points = 0;
158	        if (hasEmail(owner)) {
159	            points += 2;
160	        }
161	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
162	        if (uniqueName) {
163	            points += 1;
164	        }
165	        if (owner.getHouseholdSize() >= 3) {
166	            points += 2;
167	        }
168	        if (tenureFiscalYears(owner) > 1) {
169	            points += 3;
170	        }
171	        return points;
172	    }
173	
174	    /**
175	     * Maps the owner's {@code membershipPoints} to its numeric {@code membershipLevel}: level
176	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
177	     * {@code 4} for {@code 6} or more points.
178	     *
179	     * @param owner the owner being mapped
180	     * @return the derived membership level, between {@code 1} and {@code 4}
181	     */
182	    default Integer membershipLevel(Owner owner) {
183	        int points = membershipPoints(owner);
184	        if (points <= 1) {
185	            return 1;
186	        }
187	        if (points <= 3) {
188	            return 2;
189	        }
190	        if (points <= 5) {
191	            return 3;
192	        }
193	        return 4;
194	    }
195	
196	    /**
197	     * Computes the owner's tenure as the number of elapsed fiscal years between the owner's
198	     * {@code registrationDate} and the current date: the fiscal year of "now" minus the fiscal year
199	     * of the registration date (see {@link #fiscalYearNumber(java.time.LocalDate)}). An owner
200	     * registered and read within the same fiscal year has a tenure of {@code 0}; each subsequent
201	     * fiscal year that has started adds one. Returns {@code 0} when no registration date is present,
202	     * so an owner without a registration date has no tenure.
203	     *
204	     * @param owner the owner being mapped
205	     * @return the owner's tenure in elapsed fiscal years, or {@code 0} when no registration date is present
206	     */
207	    default long tenureFiscalYears(Owner owner) {
208	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
209	        if (registrationDate == null) {
210	            return 0;
211	        }
212	        return (long) fiscalYearNumber(java.time.LocalDate.now()) - fiscalYearNumber(registrationDate);
213	    }
214	
215	    /**
216	     * Computes the calendar year that identifies the fiscal year containing {@code date}. The fiscal
217	     * year starts on 1 July and is labelled by the calendar year in which it starts, so a date on or
218	     * after 1 July belongs to that same year's fiscal year, while a date before 1 July belongs to the
219	     * previous year's fiscal year (e.g. {@code 2026-09-06} yields {@code 2026} and {@code 2026-06-15}
220	     * yields {@code 2025}).
221	     *
222	     * @param date the date whose fiscal year is wanted
223	     * @return the calendar year the fiscal year starts in
224	     */
225	    default int fiscalYearNumber(java.time.LocalDate date) {
226	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() : date.getYear() - 1;
227	    }
228	
229	    /**
230	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, where {@code YY} is the last
231	     * two digits of the fiscal year of the (business-day-adjusted) {@code registrationDate} (e.g.
232	     * {@code 'FY26'}). Returns {@code null} when no registration date is present.
233	     *
234	     * @param owner the owner being mapped
235	     * @return the formatted fiscal year, or {@code null} when no registration date is present
236	     */
237	    default String fiscalYear(Owner owner) {
238	        if (owner.getRegistrationDate() == null) {
239	            return null;
240	        }
241	        return String.format("FY%02d", fiscalYearNumber(owner.getRegistrationDate()) % 100);
242	    }
243	
244	    /**
245	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
246	     * where {@code YY} is the last two digits of the fiscal year of the (business-day-adjusted)
247	     * {@code registrationDate} (e.g. {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the
248	     * customer code or the registration date is absent.
249	     *
250	     * @param owner the owner being mapped
251	     * @return the formatted membership number, or {@code null} when it cannot be derived
252	     */
253	    default String membershipNumber(Owner owner) {
254	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
255	            return null;
256	        }
257	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearNumber(owner.getRegistrationDate()) % 100);
258	    }
259	
260	    /**
261	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
262	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
263	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
264	     * the customer code is absent.
265	     *
266	     * @param owner the owner being mapped
267	     * @return the Luhn check digit, or {@code null} when no customer code is present
268	     */
269	    default Integer checkDigit(Owner owner) {
